#pragma once
// Per-BlockLegacy data of the original (BDS 1.6.0.15, Linux), dumped from the
// running server: src/world/block_data.cpp is generated by
// tools/re/make_block_table.py. Field offsets are listed there.
#include <cstdint>
#include <string_view>
#include <vector>

namespace bds {
struct BlockInfo {
    const char *name;   // BlockLegacy raw name (+0x28)
    const char *klass;  // C++ class of the BlockLegacy (vtable)
    std::uint64_t properties; // +0x58 BlockProperty bits
    bool solid;               // +0xaa
    std::uint8_t light_block, light_emission; // +0xb4, +0xb5
    int material;             // MaterialType (Material +0)
    bool replaceable, liquid, blocks_motion, material_solid, never_buildable; // Material +7, +8, +0x10, +0x12, +5
    float translucency;       // Material +0xc
    bool can_contain_liquid;  // vtable +0x160 (Block::canContainLiquid 0x1abb340), evaluated by the original
    bool has_property(std::uint64_t bit) const { return (properties & bit) != 0; }
};
const std::vector<BlockInfo> &block_infos();
// The entry for a legacy name; unknown names get an air-like entry.
const BlockInfo &block_info(std::string_view name);
} // namespace bds
